export const meta = {
  name: 'skf-validator-fit-decision',
  description: 'Investigate the SKF vs generic module-validator mismatch and recommend the best move',
  phases: [
    { title: 'Investigate', detail: 'four parallel scouts: provenance, convention authority, schema consumers, prior art' },
    { title: 'Recommend', detail: 'synthesize a ranked recommendation, then adversarially critique it' },
  ],
}

const REPO = '/home/armel/Projects/OSS/bmad-module-skill-forge'

const SCOUT_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['question', 'answer', 'confidence', 'evidence', 'implications'],
  properties: {
    question: { type: 'string' },
    answer: { type: 'string', description: 'Direct, specific conclusion' },
    confidence: { type: 'string', enum: ['high', 'medium', 'low'] },
    evidence: { type: 'array', items: { type: 'string' }, description: 'file:line, command output, or exact quoted lines' },
    implications: { type: 'string', description: 'What this means for the decision' },
  },
}

const RECO_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['recommendation', 'rationale', 'ranked_options', 'concrete_next_actions', 'risks'],
  properties: {
    recommendation: { type: 'string', description: 'The single best move, stated crisply' },
    rationale: { type: 'string' },
    ranked_options: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['option', 'verdict', 'why'],
        properties: {
          option: { type: 'string' },
          verdict: { type: 'string', enum: ['do', 'maybe', 'reject'] },
          why: { type: 'string' },
        },
      },
    },
    concrete_next_actions: { type: 'array', items: { type: 'string' } },
    risks: { type: 'string' },
  },
}

const CRITIQUE_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['agrees', 'strongest_objection', 'overlooked', 'verdict'],
  properties: {
    agrees: { type: 'boolean' },
    strongest_objection: { type: 'string' },
    overlooked: { type: 'array', items: { type: 'string' } },
    verdict: { type: 'string', description: 'Revised best move if the recommendation should change, else "stands"' },
  },
}

phase('Investigate')

const SCOUTS = [
  {
    label: 'provenance',
    prompt: `In the git repo at ${REPO}, determine the provenance and mutability of the \`bmad-module-builder\` skill and its validator at \`.claude/skills/bmad-module-builder/scripts/validate-module.py\`.
Specifically answer:
- Is \`.claude/skills/bmad-module-builder/\` git-tracked? Run \`git -C ${REPO} ls-files .claude/skills/bmad-module-builder | head\`.
- Is any part of \`.claude/\` gitignored? Check \`.gitignore\` and \`git -C ${REPO} check-ignore -v .claude/skills/bmad-module-builder/scripts/validate-module.py\`.
- Is this an INSTALLED BMad Builder (bmb) module that would be overwritten on reinstall? Look for install manifests, package.json bmb references, a marketplace/plugin config, and \`_bmad/bmb/\`. Check git log for whether these skill files are hand-maintained here or vendored from upstream.
Conclude clearly: editing validate-module.py in this repo would be (a) a durable committed change owned by this repo, (b) a local patch that gets overwritten on reinstall, or (c) throwaway. Cite file evidence.`,
  },
  {
    label: 'convention-authority',
    prompt: `In ${REPO}, settle whether SKF's module-manifest layout is CONFORMANT with the real BMad convention or is drift.
Facts: SKF (\`src/\`) keeps \`module.yaml\` and \`module-help.csv\` at the module ROOT and uses CSV columns \`after\`/\`before\`. The generic scaffolder validator (\`.claude/skills/bmad-module-builder/scripts/validate-module.py\`) expects them inside \`<setup-skill>/assets/\` and expects columns \`preceded-by\`/\`followed-by\`.
Investigate the INSTALLED BMad modules present in the repo — read the FIRST (header) line and the file LOCATION of: \`_bmad/bmm/module-help.csv\`, \`_bmad/core/module-help.csv\`, \`_bmad/bmb/module-help.csv\`. Do they sit at module root? Do their headers use \`after\`/\`before\` or \`preceded-by\`/\`followed-by\`?
Also read what the scaffolder EMITS: \`.claude/skills/bmad-module-builder/assets/setup-skill-template/assets/module-help.csv\` (its header) and \`.../assets/setup-skill-template/assets/module.yaml\` location.
Conclude with exact quoted header lines as evidence:
1) Is root-level module-help.csv the installed-runtime convention?
2) Is \`after\`/\`before\` the real ecosystem column convention (with \`preceded-by\`/\`followed-by\` being only the scaffolder's SOURCE form), or the reverse?
3) Therefore: is SKF conformant with the installed convention, and is the validator merely checking a pre-install SOURCE layout SKF doesn't use? Or is SKF genuinely non-conformant?`,
  },
  {
    label: 'schema-consumers',
    prompt: `In ${REPO}, determine what CONSUMES SKF's \`src/module.yaml\` and \`src/module-help.csv\`, and whether the \`after\`/\`before\` CSV columns are load-bearing.
Trace: the installer (\`tools/cli/lib/installer.js\` and siblings in tools/cli/lib), the CLI entrypoint, any JSON schema files for the module/help-csv, and the test suite (npm scripts of interest: \`validate:skills\` -> tools/validate-skills.js, \`validate:refs\` -> tools/validate-file-refs.js, \`test:install\`, \`test:cli\`, and the python tests).
Answer:
- Does anything PARSE \`after\`/\`before\` to build an ordered help menu / DAG, or is module-help.csv copied verbatim as a display manifest?
- Are there SKF-OWN tests that validate module-help.csv columns/structure?
- Is module.yaml consumed for install-time prompts (e.g. skills_output_folder, forge_data_folder, sidecar_path)?
Report which fields/columns are FUNCTIONALLY REQUIRED vs cosmetic, with file:line evidence.`,
  },
  {
    label: 'prior-art',
    prompt: `In ${REPO}, find any prior decision, discussion, or record about (a) validating the SKF module with generic BMad module-builder tooling, or (b) the choice of root-level \`module.yaml\`/\`module-help.csv\` and \`after\`/\`before\` columns vs \`preceded-by\`/\`followed-by\`.
Search: \`git -C ${REPO} log --oneline --all | head -50\` and grep git log for module-help / module.yaml / manifest / validate-module / module-builder; docs/ ; ROADMAP.md ; README.md ; any \`.decision-log.md\` or decision-log files under src/ ; an improvement-queue if present ; CONTRIBUTING or any module-authoring docs.
Report: is there an existing stance on whether SKF should be validatable by the generic VM tool? Has the after/before vs preceded-by/followed-by naming ever been discussed or deliberately chosen? Give file/commit evidence, or state plainly that there is NO prior art on this.`,
  },
]

const scouts = await parallel(
  SCOUTS.map((s) => () => agent(s.prompt, { label: s.label, phase: 'Investigate', schema: SCOUT_SCHEMA }))
)

const findings = scouts.filter(Boolean)
log(`Investigation returned ${findings.length}/${SCOUTS.length} scout reports`)

phase('Recommend')

const evidenceBlock = SCOUTS.map((s, i) => `--- SCOUT: ${s.label} ---\n${JSON.stringify(scouts[i], null, 2)}`).join('\n\n')

const recommendation = await agent(
  `You are advising Armel, who maintains the SKF (Skill Forge) BMad module in ${REPO}. He asked: "what is the best move?" regarding the fact that the GENERIC bmad-module-builder validator (\`validate-module.py\`) reports false-positive criticals on SKF because SKF stores its manifest at the module root and uses \`after\`/\`before\` CSV columns instead of the scaffolder's \`<setup>/assets/\` layout with \`preceded-by\`/\`followed-by\`.

The candidate moves are: (A) do nothing to the validator, just save the validation report; (B) teach validate-module.py to accept root-level manifests and after/before columns; (C) change SKF to match the scaffolder's layout; (D) contribute the validator fix upstream to the bmb module; (E) something else.

Here is the evidence gathered by four parallel scouts:

${evidenceBlock}

Weigh the evidence and produce a decisive recommendation. Ground every claim in the scout evidence. If the evidence shows SKF is actually CONFORMANT with the installed convention (and the validator is checking a source layout SKF doesn't use), say so plainly and let that drive the recommendation. Prefer the lowest-effort move that is correct; reject moves that fight the ecosystem convention or patch throwaway/overwritten tooling. Be concrete about next actions.`,
  { label: 'synthesize', phase: 'Recommend', schema: RECO_SCHEMA }
)

const critique = await agent(
  `You are a skeptical senior engineer. Adversarially critique the following recommendation about the SKF module vs the generic bmad-module-builder validator. Try to find where it is wrong, overconfident, or misreads the evidence. Consider: does it under- or over-weight the scout findings? Does it ignore a cheaper or more correct option? Does it recommend patching tooling that gets overwritten, or changing a module that is actually conformant? Is "do nothing" actually leaving a real footgun (e.g. someone later runs the generic VM in CI and it false-fails)?

RECOMMENDATION UNDER REVIEW:
${JSON.stringify(recommendation, null, 2)}

SCOUT EVIDENCE:
${evidenceBlock}

Return your strongest objection, anything overlooked, and — if you'd change the call — the revised best move; otherwise set verdict to "stands".`,
  { label: 'critique', phase: 'Recommend', schema: CRITIQUE_SCHEMA }
)

return { scouts, recommendation, critique }
